function getDoubled(numbers) {
  for (let i = 0; i < numbers.length; i++) {
    numbers[i] = numbers[i] * 2;
  }
  return numbers;
}

function getOdds(numbers) {
  return numbers.filter((n) => { if (n % 2 !== 0) n });
}
